// src/boilerplate/Utilities/RunningExpAverage.h.
//
// PidController's derivative filter. The logic must stay IDENTICAL to
// pid-tuner, so that servo gains tuned on the bench stay valid in flight.
// Nothing below this comment differs from the original. Do not edit this file
// on its own: change the tuner, then copy again.
#pragma once

template <typename T>
class RunningExpAverage {
    public:
        RunningExpAverage(T alpha) : alpha(alpha), isInit(false) {}

        void update(T newVal) {
            if (isInit){
                val = alpha * newVal + (1 - alpha) * val;
            }
            else {
                val = newVal;
                isInit = true;
            }
        }

        T getAvg() {
            return val;
        }

    private:
        T alpha;
        T val;
        bool isInit;
};
